const trade = $('Fetch Active Trades').item.json;
const priceData = $input.first().json;
const currentPrice = parseFloat(priceData.ltp || priceData.price || trade.current_price || trade.entry_price);

const entryPrice   = parseFloat(trade.entry_price);
const sl           = parseFloat(trade.sl);
const target       = parseFloat(trade.current_target);
const trailingPct  = parseFloat(trade.trailing_pct || 0.5);
const highest      = Math.max(parseFloat(trade.highest_price || entryPrice), currentPrice);
const pnl          = parseFloat((currentPrice - entryPrice).toFixed(2));
const pnlPct       = parseFloat(((pnl / entryPrice) * 100).toFixed(4));

let action = 'UPDATE';
let newSL = sl;
let newTarget = target;
let newStatus = trade.status;
let exitReason = null;

// CHECK STOP LOSS
if (currentPrice <= sl) {
  action = 'CLOSE';
  newStatus = 'STOP_LOSS_HIT';
  exitReason = 'SL Hit';
}
// CHECK TARGET
else if (currentPrice >= target) {
  action = 'TRAIL';
  newStatus = 'TRAILING';
  const step = parseFloat((entryPrice * trailingPct / 100).toFixed(2));
  newSL = trade.target_count === 0 ? entryPrice : parseFloat((target - step).toFixed(2));
  newTarget = parseFloat((target + step).toFixed(2));
}

return [{
  json: {
    ...trade,
    current_price: currentPrice,
    highest_price: highest,
    pnl, pnl_pct: pnlPct,
    new_sl: newSL,
    new_target: newTarget,
    new_status: newStatus,
    exit_reason: exitReason,
    action
  }
}];
